<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import UiDialog from '../../components/ui/UiDialog.vue'
import UiStatePanel from '../../components/ui/UiStatePanel.vue'
import UiConfirmDialog from '../../components/ui/UiConfirmDialog.vue'
import { errorText } from '../models/api'
import { operationsApi, type Audit, type Binding, type Rule, type Source } from './api'
import '../models/models.css'
import { useProjectCapabilities } from '../projects/capabilities'
const { rules: canManage, audit: canAudit, can } = useProjectCapabilities()
import { requiresReload } from '../projects/writeRecovery'
const needsReload=ref(false)
const rules=ref<Rule[]>([]),audit=ref<Audit[]>([]),sources=ref<Source[]>([]),phase=ref<'loading'|'ready'|'error'>('loading'),error=ref(''),message=ref(''),failed=ref(false),busy=ref(false),query=ref('')
const editOpen=ref(false),draft=ref<Rule|null>(null),original=ref<Rule>(),bindingRule=ref<Rule|null>(null),bindingOpen=ref(false),bindings=ref<Binding[]>([]),sourceId=ref(''),validation=ref<Binding|null>(null),deleteTarget=ref<Rule|null>(null)
const labels=ref(''),requires=ref(''),roi=ref('null'),thresholds=ref('{}'),bands=ref('[]'),escalation=ref('null'),scope=ref('null')
let controller:AbortController|undefined, bindingController:AbortController|undefined,disposed=false
const filtered=computed(()=>rules.value.filter(r=>`${r.ruleId} ${r.name} ${r.targetLabels.join(' ')}`.toLowerCase().includes(query.value.toLowerCase())))
const operators=['PRESENCE','IN_REGION','LINE_CROSS','DWELL','COUNT','AREA_RATIO','RATE','ABSENCE']
const selectedSource=computed(()=>sources.value.find(s=>s.sourceId===sourceId.value))
watch(sourceId,()=>{validation.value=null})
async function refresh(){controller?.abort();controller=new AbortController();const signal=controller.signal;try{const [list,logs,caps]=await Promise.all([operationsApi.rules(signal),canAudit.value ? operationsApi.audit(signal) : Promise.resolve([]),can('project.streams.view') ? operationsApi.sources(signal) : Promise.resolve([])]);if(!disposed&&!signal.aborted){rules.value=list;audit.value=logs;sources.value=caps;phase.value='ready';needsReload.value=false}}catch(e){if(!disposed&&!signal.aborted){phase.value='error';error.value=errorText(e)}}}
async function action(run:()=>Promise<unknown>,text:string,after?:()=>Promise<void>){if(busy.value||needsReload.value||!canManage.value)return false;busy.value=true;try{await run();if(disposed)return false;message.value=text;failed.value=false;await refresh();if(!disposed&&after)await after();return !disposed}catch(e){if(!disposed){needsReload.value=needsReload.value||requiresReload(e);message.value=errorText(e)+(needsReload.value?' 请关闭弹窗并刷新核验后再操作。':'');failed.value=true};return false}finally{busy.value=false}}
function edit(rule?:Rule){if(!canManage.value||needsReload.value)return;original.value=rule?JSON.parse(JSON.stringify(rule)):undefined;draft.value=rule?JSON.parse(JSON.stringify(rule)):{ruleId:'',name:'',ruleVersion:1,enabled:true,subjectKind:'track',operator:'PRESENCE',requires:[],targetLabels:[],thresholds:{}};const r=draft.value!;labels.value=r.targetLabels.join(', ');requires.value=r.requires.join(', ');roi.value=JSON.stringify(r.roi??null,null,2);thresholds.value=JSON.stringify(r.thresholds,null,2);bands.value=JSON.stringify(r.severityBands??[],null,2);escalation.value=JSON.stringify(r.escalation??null,null,2);scope.value=JSON.stringify(r.scope??null,null,2);message.value='';editOpen.value=true}
function parse(text:string,kind:'object'|'array',nullable=false){const value=JSON.parse(text);if(nullable&&value===null)return undefined;if(kind==='array'? !Array.isArray(value) : value===null||typeof value!=='object'||Array.isArray(value))throw new Error('JSON 类型不正确，请检查区域、阈值和高级字段');return value}
async function save(){if(!draft.value)return;try{const rule={...draft.value,targetLabels:labels.value.split(',').map(s=>s.trim()).filter(Boolean),requires:requires.value.split(',').map(s=>s.trim()).filter(Boolean),roi:parse(roi.value,'object',true),thresholds:parse(thresholds.value,'object'),severityBands:parse(bands.value,'array'),escalation:parse(escalation.value,'object',true),scope:parse(scope.value,'object',true)};if(!operators.includes(rule.operator)&&rule.enabled)throw new Error('该算子尚未实现，不能启用规则');if(await action(()=>operationsApi.saveRule(rule,original.value),'规则已保存并记录审计。'))editOpen.value=false}catch(e){message.value=errorText(e);failed.value=true}}
async function showBindings(rule:Rule){message.value='';bindingController?.abort();bindingController=new AbortController();const signal=bindingController.signal;bindingRule.value=rule;bindings.value=[];validation.value=null;sourceId.value='';bindingOpen.value=true;try{const value=await operationsApi.bindings(rule.ruleId,signal);if(!disposed&&!signal.aborted)bindings.value=value}catch(e){if(!signal.aborted){message.value=errorText(e);failed.value=true}}}
async function validate(){const rule=bindingRule.value,source=selectedSource.value;if(!rule||!source)return;await action(async()=>{validation.value=await operationsApi.validate(rule.ruleId,source)},'能力校验完成，请检查结果。')}
async function reloadBindings(id:string){
  if(disposed)return
  bindingController?.abort();bindingController=new AbortController();const signal=bindingController.signal
  try{const [list,rule]=await Promise.all([operationsApi.bindings(id,signal),operationsApi.rule(id,signal)]);if(!disposed&&!signal.aborted){bindings.value=list;bindingRule.value=rule;validation.value=null}}
  catch(e){if(!disposed&&!signal.aborted){needsReload.value=true;throw e}}
}
async function bind(){const rule=bindingRule.value,source=selectedSource.value;if(!rule||!source||!validation.value?.accepted)return;await action(()=>operationsApi.bind(rule.ruleId,source,rule.ruleVersion),'绑定已保存并记录审计。',()=>reloadBindings(rule.ruleId))}
async function remove(){const rule=deleteTarget.value;if(!rule)return;await action(()=>operationsApi.removeRule(rule.ruleId,rule.ruleVersion),'规则已删除并记录审计。');deleteTarget.value=null}
async function unbind(binding:Binding){const rule=bindingRule.value;if(!rule)return;await action(()=>operationsApi.unbind(rule.ruleId,binding.sourceId,rule.ruleVersion),'绑定已解除。',()=>reloadBindings(rule.ruleId))}
onMounted(refresh);onBeforeUnmount(()=>{disposed=true;controller?.abort();bindingController?.abort()})
</script>
<template><section class="model-workspace"><div class="model-actions page-actions"><UiButton class="secondary-button" @click="refresh">刷新规则</UiButton><UiButton v-if="canManage" class="primary-button"  :disabled="busy||needsReload" @click="edit()">新增规则</UiButton></div>
<p class="operation-feedback">每个视频流当前绑定一个模型。COMPOSITE、RELATION、METRIC_THRESHOLD 尚未实现；多模型同时识别与结果组合需要后端编排能力。</p>
<p v-if="message" class="operation-feedback" :class="{'is-error':failed,'is-success':!failed}" role="status">{{message}}</p><div class="model-toolbar"><label>搜索规则<UiInput v-model="query" /></label></div><UiStatePanel v-if="phase!=='ready'" :state="phase" :message="error" @retry="refresh"/><UiStatePanel v-else-if="!filtered.length" state="empty" title="暂无规则"/><div v-else class="model-grid"><article v-for="rule in filtered" :key="rule.ruleId" class="model-card"><h3>{{rule.name}}</h3><code>{{rule.ruleId}} / v{{rule.ruleVersion}}</code><p>{{rule.operator}} · {{rule.enabled?'已启用':'已暂停'}}</p><p class="model-muted">类别：{{rule.targetLabels.join(' · ')||'全部'}} · 能力：{{rule.requires.join(' · ')||'无额外要求'}}</p><div class="model-actions"><UiButton v-if="canManage" class="secondary-button"  :disabled="busy||needsReload" @click="edit(rule)">编辑规则</UiButton><UiButton class="secondary-button"  :disabled="busy||needsReload" @click="showBindings(rule)">{{canManage?'校验与绑定':'查看绑定'}}</UiButton><UiButton v-if="canManage" class="secondary-button danger-text"  :disabled="busy||needsReload" @click="deleteTarget=rule">删除规则</UiButton></div></article></div>
<section v-if="canAudit" class="model-panel"><header><h3>规则审计</h3></header><p v-if="!audit.length" class="model-muted">暂无记录</p><div v-for="(entry,index) in audit.slice(-50).reverse()" :key="index" class="dataset-row"><div><strong>{{entry.action}} · {{entry.ruleId}} · v{{entry.ruleVersion}}</strong><p>{{entry.actor}} · {{entry.timestamp}} · {{entry.sourceId||''}} {{entry.code||''}}</p></div></div></section>
<UiDialog v-model:open="editOpen" title="规则编辑" :busy="busy"><form v-if="draft" class="model-form" @submit.prevent="save"><fieldset :disabled="busy || !canManage"><div class="model-fields"><label>规则 ID<UiInput v-model="draft.ruleId" required maxlength="64" pattern="[A-Za-z0-9_.-]+" :readonly="!!original"/></label><label>规则名称<UiInput v-model="draft.name" required maxlength="256"/></label><label>算子<UiSelect v-model="draft.operator"><UiOption v-for="operator in operators" :key="operator" :value="operator">{{operator}}</UiOption><UiOption v-if="!operators.includes(draft.operator)" :value="draft.operator">{{draft.operator}}（尚未实现）</UiOption></UiSelect></label><label>主体<UiSelect v-model="draft.subjectKind"><UiOption v-for="subject in ['track','frame','roi','metric','source']" :key="subject" :value="subject">{{subject}}</UiOption></UiSelect></label><label>目标类别（逗号分隔）<UiInput v-model="labels"/></label><label>所需能力（逗号分隔）<UiInput v-model="requires" placeholder="BOX, TRACK"/></label><label>区域 ID<UiInput v-model="draft.roiId"/></label><label class="model-check"><UiInput v-model="draft.enabled" type="checkbox"/>启用规则</label><label class="wide">阈值 JSON<UiInput type="textarea" v-model="thresholds" rows="4" required/></label><label class="wide">区域几何 JSON（无区域填 null）<UiInput type="textarea" v-model="roi" rows="4" required/></label></div><UiCollapse class="parameter-audit"><template #title>高级字段</template><div class="model-fields"><label>严重度分段 JSON<UiInput type="textarea" v-model="bands" rows="4"/></label><label>升级策略 JSON<UiInput type="textarea" v-model="escalation" rows="4"/></label><label>作用域 JSON<UiInput type="textarea" v-model="scope" rows="4"/></label></div></UiCollapse></fieldset><p class="model-muted">保存携带读取时的修订号，服务器原子校验并拒绝过期覆盖。冲突后请保留草稿，关闭弹窗并刷新后重新编辑。</p><p v-if="message" class="operation-feedback" :class="{'is-error':failed}" role="status">{{message}}</p><footer><UiButton type="button" class="secondary-button" :disabled="busy" @click="editOpen=false">取消</UiButton><UiButton class="primary-button" :disabled="busy||needsReload||!canManage">保存规则</UiButton></footer></form></UiDialog>
<UiDialog v-model:open="bindingOpen" title="规则能力校验与绑定" :busy="busy"><div class="model-detail"><h3>{{bindingRule?.name}}</h3><label>实际来源<UiSelect v-model="sourceId" :disabled="busy"><UiOption value="">请选择运行中的来源</UiOption><UiOption v-for="source in sources" :key="source.sourceId" :value="source.sourceId">{{source.sourceId}} / {{source.modelId||'无模型'}}</UiOption></UiSelect></label><p v-if="selectedSource" class="model-muted">来源能力：{{selectedSource.capabilities.join(' · ')}}</p><p v-if="!sources.length" class="model-muted">没有实时来源。请先启用视频流并绑定模型。</p><div class="model-actions"><UiButton class="secondary-button" :disabled="busy||needsReload||!canManage||!selectedSource" @click="validate">校验能力</UiButton><UiButton class="primary-button" :disabled="busy||needsReload||!canManage||!validation?.accepted" @click="bind">保存绑定</UiButton></div><p v-if="validation" class="operation-feedback" :class="{'is-error':!validation.accepted,'is-success':validation.accepted}">{{validation.accepted?'能力满足，可提交绑定':validation.message||validation.code}} {{validation.missing?.join(', ')}}</p><p v-if="message" class="operation-feedback" :class="{'is-error':failed}" role="status">{{message}}</p><h4>已有绑定</h4><p v-if="!bindings.length" class="model-muted">暂无绑定</p><div v-for="binding in bindings" :key="binding.sourceId" class="dataset-row"><span>{{binding.sourceId}} · {{binding.accepted?'已接受':binding.message||binding.code}}</span><UiButton v-if="canManage" class="secondary-button" :disabled="busy||needsReload" @click="unbind(binding)">解除绑定</UiButton></div></div></UiDialog>
<UiConfirmDialog :open="!!deleteTarget" title="删除规则" :description="`删除 ${deleteTarget?.name} 及其绑定，保留审计历史。`" confirm-label="确认删除规则" tone="danger" :busy="busy" @update:open="open=>{if(!open)deleteTarget=null}" @confirm="remove"/></section></template>
